css:
.ds-volta { --ds-cover-bg: var(--ds-paper); }
.ds-volta .ds-section h2 { font-family: var(--font-display); }
.ds-volta .ds-chip { border-width: 2px; border-color: var(--ds-edge); }
.ds-volta .v-edge { fill: var(--ds-edge); } .ds-volta .v-volt { fill: var(--ds-volt); } .ds-volta .v-acid { fill: var(--ds-acid); } .ds-volta .v-cobalt { fill: var(--ds-cobalt); } .ds-volta .v-positive { fill: var(--ds-positive); }
.ds-volta .v-rim { stroke: var(--ds-edge); stroke-width: 2; } .ds-volta .v-stripe line { stroke: var(--ds-edge); stroke-width: 4; }
.ds-volta .v-svg-label { font-family: var(--font-body); font-size: 13px; font-weight: 600; letter-spacing: .08em; fill: var(--ds-ink); } .ds-volta .v-on-cobalt { fill: var(--ds-on-cobalt); }
.ds-volta .v-svg-mono { font-family: var(--font-mono); font-size: 12px; letter-spacing: .06em; fill: var(--ds-ink); } .ds-volta .v-muted-fill { fill: var(--ds-ink-muted); }
.ds-volta .v-muted { color: var(--ds-ink-muted); } .ds-volta .v-volt-ink { color: var(--ds-volt-ink); }
.ds-volta .v-btn { font-family: var(--font-body); font-size: 15px; font-weight: 600; line-height: 20px; padding: 10px 16px; border: 2px solid var(--ds-edge); border-radius: 4px; background: var(--ds-paper-raised); color: var(--ds-ink); box-shadow: var(--ds-shadow-hard); cursor: pointer; transition: transform 80ms ease-out, box-shadow 80ms ease-out; }
.ds-volta .v-btn:hover { transform: translate(-2px, -2px); box-shadow: 6px 6px 0 0 var(--ds-edge); }
.ds-volta .v-btn:active { transform: translate(4px, 4px); box-shadow: 0 0 0 0 var(--ds-edge); }
.ds-volta .v-btn:focus-visible { outline: none; box-shadow: var(--ds-focus-ring); }
.ds-volta .v-btn-primary { background: var(--ds-volt); color: var(--ds-on-volt); } .ds-volta .v-btn-acid { background: var(--ds-acid); color: var(--ds-on-acid); }
.dark .ds-volta .v-btn:hover { box-shadow: 6px 6px 0 0 var(--ds-volt); }
.ds-volta .v-tag { display: inline-flex; align-items: center; gap: 6px; padding: 3px 8px; border-radius: 4px; font-size: 12px; font-weight: 600; letter-spacing: .08em; text-transform: uppercase; line-height: 16px; background: var(--ds-paper-sunk); color: var(--ds-ink); }
.ds-volta .v-tag-acid { background: var(--ds-acid); color: var(--ds-on-acid); } .ds-volta .v-tag-positive { background: var(--ds-positive-soft); color: var(--ds-positive); } .ds-volta .v-tag-caution { background: var(--ds-caution-soft); color: var(--ds-caution); } .ds-volta .v-tag-cobalt { background: var(--ds-cobalt-soft); color: var(--ds-cobalt); }
.ds-volta .v-stat { display: grid; gap: 6px; padding: 20px 24px; background: var(--ds-paper-raised); border: 2px solid var(--ds-edge); box-shadow: var(--ds-shadow-hard-lg); min-width: 200px; }
.ds-volta .v-stat-accent { background: var(--ds-volt); color: var(--ds-on-volt); } .ds-volta .v-stat-accent .t-label, .ds-volta .v-stat-accent .v-delta { color: var(--ds-on-volt); }
.ds-volta .ds-stats { gap: 32px; }
.ds-volta .v-delta { font-size: 13px; color: var(--ds-ink-muted); } .ds-volta .v-up { color: var(--ds-positive); } .ds-volta .v-down { color: var(--ds-negative); }
.ds-volta .v-callout { padding: 14px 16px; border: 2px solid var(--ds-edge); line-height: 1.5; font-size: 15px; } .ds-volta .v-callout strong { font-weight: 600; }
.ds-volta .v-callout-info { background: var(--ds-cobalt-soft); } .ds-volta .v-callout-positive { background: var(--ds-positive-soft); } .ds-volta .v-callout-negative { background: var(--ds-negative-soft); }
.ds-volta .v-hard { border: 2px solid var(--ds-edge); box-shadow: var(--ds-shadow-hard-lg); background: var(--ds-paper-raised); }
.ds-volta .v-card { padding: 24px; display: grid; gap: 10px; justify-items: start; transition: transform 120ms ease-out; } .ds-volta .v-card:hover { transform: translate(-2px, -2px); }
.ds-volta .v-card h3 { margin: 0; } .ds-volta .v-card-body { margin: 0; line-height: 1.5; color: var(--ds-ink-muted); max-width: 52ch; } .ds-volta .v-card .v-btn { margin-top: 8px; }
.ds-volta .v-sample { background: var(--ds-paper); padding: 40px 20px 64px; border-top: 2px solid var(--ds-edge); border-bottom: 2px solid var(--ds-edge); }
.ds-volta .v-sample-in { max-width: 1100px; margin: 0 auto; }
.ds-volta .v-sample-top { display: flex; justify-content: space-between; flex-wrap: wrap; gap: 8px; padding-bottom: 12px; border-bottom: 2px solid var(--ds-edge); }
.ds-volta .v-sample-h { margin-top: 32px; max-width: 16ch; }
.ds-volta .v-sample-lede { margin-top: 16px; max-width: 56ch; color: var(--ds-ink-muted); }
.ds-volta .v-sample-stats { display: grid; gap: 32px; margin-top: 36px; }
.ds-volta .v-sample-grid { display: grid; gap: 32px; margin-top: 40px; }
.ds-volta .v-panel { padding: 20px; min-width: 0; } .ds-volta .v-panel .t-label { display: block; margin-bottom: 12px; }
@container (min-width: 760px) { .ds-volta .v-sample { padding: 56px 40px 80px; } .ds-volta .v-sample-stats { grid-template-columns: 1fr 1fr 1fr; } .ds-volta .v-sample-grid { grid-template-columns: 3fr 2fr; } }

.ds-volta { --ds-hand-ink: var(--ds-edge); --ds-hand-fill: var(--ds-volt); --ds-hand-fill2: var(--ds-cobalt); --ds-hand-muted: var(--ds-paper-sunk); --ds-hand-ground: var(--ds-paper-raised); --ds-hand-stroke: 2; --ds-hand-cap: square; --ds-hand-shadow: var(--ds-edge); --ds-hand-bg: var(--ds-paper);
  --ds-tpl-edge: 2px solid var(--ds-edge); --ds-tpl-radius: 0; --ds-tpl-tile-shadow: var(--ds-shadow-hard); --ds-tpl-rule: 2px solid var(--ds-edge); --ds-tag-radius: 4px; --ds-slide-title-bg: var(--ds-volt); --ds-slide-title-fg: var(--ds-on-volt); --ds-slide-split-b: var(--ds-cobalt); --ds-slide-split-b-fg: var(--ds-on-cobalt); }
.dark .ds-volta { --ds-hand-shadow: var(--ds-volt); }
.ds-volta .h-num { font-family: var(--font-mono); font-weight: 600; }
.ds-volta .ds-tpl-tag.is-idle { background: var(--ds-paper-sunk); }
.ds-volta .ds-tpl-stage-title .ds-tpl-stage-foot { border-top-width: 2px; }
.ds-volta .ds-tpl-split-a { color: var(--ds-on-volt); }
